import { useState } from "react";

const GlobalStyles = () => (
  <style>{`
    @import url('https://fonts.googleapis.com/css2?family=Syne:wght@400;600;700;800&family=DM+Sans:opsz,wght@9..40,300;9..40,400;9..40,500&display=swap');
    body { font-family: 'DM Sans', sans-serif; margin: 0; }
    .font-syne { font-family: 'Syne', sans-serif; }

    @keyframes fade-up {
      from { opacity: 0; transform: translateY(20px); }
      to   { opacity: 1; transform: translateY(0); }
    }
    @keyframes fade-in {
      from { opacity: 0; } to { opacity: 1; }
    }
    @keyframes float {
      0%,100% { transform: translateY(0); }
      50%     { transform: translateY(-8px); }
    }
    @keyframes shimmer {
      0%   { background-position: -200% center; }
      100% { background-position:  200% center; }
    }

    .anim-fade-up  { animation: fade-up .55s ease both; }
    .anim-d1 { animation-delay: .08s; }
    .anim-d2 { animation-delay: .16s; }
    .anim-d3 { animation-delay: .24s; }
    .anim-d4 { animation-delay: .32s; }
    .anim-d5 { animation-delay: .40s; }

    .shimmer-btn {
      background: linear-gradient(90deg, #1A4A8A 0%, #2E7DF7 45%, #1A4A8A 100%);
      background-size: 200% auto;
      animation: shimmer 3s linear infinite;
    }
    .shimmer-btn:hover { box-shadow: 0 8px 24px rgba(46,125,247,.35); }

    .input-field {
      width: 100%;
      padding: .75rem 1rem;
      border-radius: 10px;
      border: 1.5px solid #E2E8F0;
      font-family: 'DM Sans', sans-serif;
      font-size: .9rem;
      color: #1C2B40;
      background: #F8FAFC;
      outline: none;
      transition: border-color .2s, box-shadow .2s, background .2s;
    }
    .input-field::placeholder { color: #94A3B8; }
    .input-field:focus {
      border-color: #2E7DF7;
      background: #fff;
      box-shadow: 0 0 0 3px rgba(46,125,247,.1);
    }

    .dot-grid {
      background-image: radial-gradient(circle, #2E7DF718 1.2px, transparent 1.2px);
      background-size: 24px 24px;
    }

    .panel-card {
      animation: float 5s ease-in-out infinite;
    }
    .panel-card-2 {
      animation: float 6s ease-in-out infinite;
      animation-delay: 1.5s;
    }

    .tab-active {
      background: #fff;
      color: #0B1F3A;
      box-shadow: 0 1px 4px rgba(0,0,0,.1);
    }
    .tab-inactive {
      color: #64748B;
    }
    .tab-inactive:hover { color: #1C2B40; }
  `}</style>
);

export default function Login() {
  const [role, setRole] = useState("student");
  const [showPass, setShowPass] = useState(false);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const roles = [
    { id: "student", label: "Student",       emoji: "🎓" },
    { id: "company", label: "Company",        emoji: "🏢" },
    { id: "admin",   label: "Admin",          emoji: "🏛️" },
  ];

  const roleConfig = {
    student: {
      placeholder: "university@edu.dz",
      hint: "Use your university email address",
      color: "text-blue-600",
      accent: "#2E7DF7",
    },
    company: {
      placeholder: "contact@company.com",
      hint: "Use your company email address",
      color: "text-slate-700",
      accent: "#334155",
    },
    admin: {
      placeholder: "admin@university.dz",
      hint: "Administration accounts only",
      color: "text-emerald-600",
      accent: "#059669",
    },
  };

  const cfg = roleConfig[role];

  return (
    <>
      <GlobalStyles />
      <div className="min-h-screen flex bg-slate-50 overflow-hidden">

        {/* ── LEFT PANEL ── */}
        <div className="hidden lg:flex lg:w-[52%] bg-slate-900 flex-col relative overflow-hidden">

          {/* Background layers */}
          <div className="absolute inset-0 dot-grid opacity-50" />
          <div className="absolute bottom-0 left-0 w-96 h-96 bg-blue-600/20 rounded-full blur-3xl" />
          <div className="absolute top-20 right-0 w-64 h-64 bg-blue-400/10 rounded-full blur-2xl" />
          {/* Logo */}
          <div className="relative p-10">
            <a href="/" className="font-syne font-extrabold text-2xl text-white tracking-tight">
              Stag<span className="text-blue-400">.</span>io
            </a>
          </div>

          {/* Central content */}
          <div className="flex-1 flex flex-col justify-center px-12 pb-16 relative">
            <p className="text-xs font-semibold tracking-widest text-blue-400 uppercase mb-4">
              Welcome back
            </p>
            <h1 className="font-syne font-extrabold text-white leading-tight mb-5"
              style={{ fontSize: "clamp(2rem, 3.5vw, 3rem)", letterSpacing: "-1px" }}>
              Your internship<br />
              journey starts<br />
              <span className="text-blue-400">right here.</span>
            </h1>
            <p className="text-slate-400 font-light leading-relaxed text-sm max-w-sm">
              Sign in to access offers, manage applications,
              and track your placement — all in one place.
            </p>

            {/* Floating cards */}
            <div className="mt-12 relative h-44">
              {/* Card 1 */}
              <div className="panel-card absolute left-0 top-0 bg-white/10 backdrop-blur-sm border border-white/10 rounded-2xl p-4 w-64">
                <div className="flex items-center gap-3 mb-3">
                  <div className="w-8 h-8 bg-blue-500/30 rounded-lg flex items-center justify-center text-sm">🎓</div>
                  <div>
                    <div className="text-xs font-semibold text-white">Amira Benali</div>
                    <div className="text-xs text-slate-400">L3 Informatique · IFA</div>
                  </div>
                  <span className="ml-auto text-xs text-emerald-400 font-semibold bg-emerald-400/10 px-2 py-0.5 rounded-full">Placed ✓</span>
                </div>
                <div className="flex gap-1.5">
                  {["React","Node.js","SQL"].map(t=>(
                    <span key={t} className="text-xs bg-blue-500/20 text-blue-300 px-2 py-0.5 rounded-full">{t}</span>
                  ))}
                </div>
              </div>

              {/* Card 2 */}
              <div className="panel-card-2 absolute right-0 bottom-0 bg-white/10 backdrop-blur-sm border border-white/10 rounded-2xl p-4 w-56">
                <div className="text-xs text-slate-400 mb-1">New match</div>
                <div className="font-syne font-bold text-white text-sm mb-1">Full-Stack Dev</div>
                <div className="text-xs text-slate-400 mb-2">Sonatrach Digital · Alger</div>
                <div className="flex items-center justify-between">
                  <span className="text-xs text-blue-400">6 months</span>
                  <span className="text-xs font-semibold text-white bg-blue-600 px-2.5 py-1 rounded-lg">Apply</span>
                </div>
              </div>
            </div>
          </div>

          {/* Bottom note */}
          <div className="relative px-12 pb-8">
            <p className="text-xs text-slate-500">
              © 2025–2026 · L3TI Workshop (Atelier) · IFA · 2nd Semester
            </p>
          </div>
        </div>

        {/* ── RIGHT PANEL ── */}
        <div className="flex-1 flex flex-col justify-center items-center px-6 py-12 relative">

          {/* Mobile logo */}
          <div className="lg:hidden mb-8 self-start">
            <a href="/" className="font-syne font-extrabold text-xl text-slate-900">
              Stag<span className="text-blue-500">.</span>io
            </a>
          </div>

          <div className="w-full max-w-md">

            {/* Header */}
            <div className="anim-fade-up mb-8">
              <h2 className="font-syne font-extrabold text-slate-900 text-3xl tracking-tight mb-1">
              Sign i</h2>
              <p className="text-slate-500 text-sm font-light">
                Don't have an account?{" "}
                <a href="/register" className="text-blue-600 font-medium hover:underline">Create one →</a>
              </p>
            </div>
            

            {/* Role tabs */}
            <div className="anim-fade-up anim-d1 bg-slate-100 rounded-xl p-1 flex mb-7">
              {roles.map(r => (
                <button
                  key={r.id}
                  onClick={() => setRole(r.id)}
                  className={`flex-1 flex items-center justify-center gap-1.5 py-2 rounded-lg text-sm font-medium transition-all duration-200 ${
                    role === r.id ? "tab-active" : "tab-inactive"
                  }`}
                >
                  <span>{r.emoji}</span>
                  <span>{r.label}</span>
                </button>
              ))}
            </div>

            {/* Form */}
            <div className="space-y-5">

              {/* Email */}
              <div className="anim-fade-up anim-d2">
                <label className="block text-sm font-medium text-slate-700 mb-1.5">Email</label>
                <input
                  type="email"
                  value={email}
                  onChange={e => setEmail(e.target.value)}
                  placeholder={cfg.placeholder}
                  className="input-field"
                />
                <p className="text-xs text-slate-400 mt-1">{cfg.hint}</p>
              </div>

              {/* Password */}!
              <div className="anim-fade-up anim-d3">
                <div className="flex justify-between items-center mb-1.5">
                  <label className="text-sm font-medium text-slate-700">Password</label>
                  <a href="/forgot-password" className="text-xs text-blue-600 hover:underline font-medium">
                    Forgot password?
                  </a>
                </div>
                <div className="relative">
                  <input
                    type={showPass ? "text" : "password"}
                    value={password}
                    onChange={e => setPassword(e.target.value)}
                    placeholder="••••••••"
                    className="input-field pr-11"
                  />
                  <button
                    type="button"
                    onClick={() => setShowPass(!showPass)}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 text-sm transition-colors"
                  >
                    {showPass ? "🙈" : "👁️"}
                  </button>
                </div>
              </div>

              {/* Remember me */}
              <div className="anim-fade-up anim-d4 flex items-center gap-2">
                <input
                  type="checkbox"
                  id="remember"
                  className="w-4 h-4 accent-blue-600 rounded cursor-pointer"
                />
                <label htmlFor="remember" className="text-sm text-slate-600 cursor-pointer">
                  Keep me signed in
                </label>
              </div>

              {/* Submit */}
              <div className="anim-fade-up anim-d5">
                <button
                  type="button"
                  className="shimmer-btn w-full text-white font-semibold py-3 rounded-xl text-sm transition-all duration-200"
                >
                  Sign in to Stag.io →
                </button>
              </div>

            </div>

            {/* Divider */}
            <div className="anim-fade-up anim-d5 my-7 flex items-center gap-3">
              <hr className="flex-1 border-slate-200" />
              <span className="text-xs text-slate-400 font-medium">or continue with</span>
              <hr className="flex-1 border-slate-200" />
            </div>
            {/* OAuth placeholder */}
            <div className="anim-fade-up anim-d5">
              <button className="w-full flex items-center justify-center gap-2.5 border border-slate-200 rounded-xl py-2.5 text-sm font-medium text-slate-700 bg-white hover:bg-slate-50 hover:border-slate-300 transition-all duration-200">
                <svg className="w-4 h-4" viewBox="0 0 24 24">
                  <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
                  <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>
                  <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"/>
                  <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/>
                </svg>
                Continue with Google
              </button>
            </div>

            {/* Footer note */}
            <p className="text-center text-xs text-slate-400 mt-8">
              By signing in you agree to our{" "}
              <a href="#" className="underline hover:text-slate-600">Terms</a>
              {" "}and{" "}
              <a href="#" className="underline hover:text-slate-600">Privacy Policy</a>.
            </p>
    </div>
   </div>
   </div>
    </>
  );
}

